package io.clipbridge.android;
import org.json.*;
import java.util.*;
final class GroupStateOps {
    static JSONObject empty()throws Exception{return new JSONObject().put("groups",new JSONArray());}
    static JSONObject find(JSONObject state,String id)throws Exception{JSONArray groups=state.getJSONArray("groups");for(int i=0;i<groups.length();i++)if(groups.getJSONObject(i).getString("id").equals(id))return groups.getJSONObject(i);return null;}
    static boolean advances(JSONObject group,JSONObject old,JSONObject next)throws Exception{if(GroupCrypto.certHash(old).equals(GroupCrypto.certHash(next)))return true;String target=old.getJSONObject("member").getString("id");Set<String> known=new HashSet<>();known.add(GroupCrypto.certHash(old));List<JSONObject> candidates=new ArrayList<>();candidates.add(next);JSONObject feeds=group.getJSONObject("feeds");for(String author:GroupCrypto.keys(feeds)){JSONArray certs=feeds.getJSONObject(author).getJSONArray("certificates");for(int i=0;i<certs.length();i++)candidates.add(certs.getJSONObject(i));}for(int pass=0;pass<128;pass++){boolean changed=false;for(JSONObject c:candidates){if(!c.getJSONObject("member").getString("id").equals(target)||c.optString("admission").isEmpty()||!known.contains(c.optString("previous")))continue;JSONObject issuer=group.getJSONObject("members").optJSONObject(c.getString("issuer"));if(issuer==null||!GroupCrypto.verify(issuer.getJSONObject("member"),GroupCrypto.certData(c),c.getString("signature")))continue;changed|=known.add(GroupCrypto.certHash(c));}if(!changed)break;}return known.contains(GroupCrypto.certHash(next));}
    static JSONObject merge(JSONObject state,JSONObject group)throws Exception{
        JSONArray deleted=state.optJSONArray("deletedGroups");if(deleted!=null&&GroupCrypto.contains(deleted,group.getString("id")))throw new IllegalStateException("同步组已从本机删除");GroupCrypto.validate(group);JSONObject identity=state.getJSONObject("identity"),self=identity.getJSONObject("member");String own=self.getString("id");JSONObject ownCert=group.getJSONObject("members").optJSONObject(own);if(ownCert==null||!GroupCrypto.same(ownCert.getJSONObject("member"),self))throw new SecurityException("本机身份不匹配");
        JSONObject old=find(state,group.getString("id"));if(old==null){if(state.getJSONArray("groups").length()>=4)throw new IllegalStateException("最多保存 4 个同步组");if(!group.has("suppressedPeers"))group.put("suppressedPeers",new JSONArray());if(!group.has("publishedSequence"))group.put("publishedSequence",0);state.getJSONArray("groups").put(group);return group;}
        if(!GroupCrypto.certHash(old.getJSONObject("root")).equals(GroupCrypto.certHash(group.getJSONObject("root")))||!old.getString("directoryKey").equals(group.getString("directoryKey")))throw new SecurityException("同步组身份发生变化");
        if(GroupCrypto.contains(old.getJSONArray("removed"),own)&&group.getLong("sequence")>old.getLong("sequence"))throw new SecurityException("本机已被移出同步组");
        if(group.getLong("sequence")<old.getLong("sequence")){group.put("sequence",old.getLong("sequence")).put("ownCertificates",old.getJSONArray("ownCertificates")).put("ownRemoved",old.getJSONArray("ownRemoved"));}
        else if(group.getLong("sequence")==old.getLong("sequence")&&!java.security.MessageDigest.isEqual(GroupCrypto.feedData(GroupCrypto.feed(group,identity)),GroupCrypto.feedData(GroupCrypto.feed(old,identity))))throw new SecurityException("成员状态同时修改，请重试");
        for(String id:GroupCrypto.keys(group.getJSONObject("members")))if(!old.getJSONObject("members").has(id)){String issuer=group.getJSONObject("members").getJSONObject(id).getString("issuer");if(GroupCrypto.contains(old.getJSONArray("removed"),issuer)&&(!group.getJSONObject("members").has(issuer)||!advances(group,old.getJSONObject("members").getJSONObject(issuer),group.getJSONObject("members").getJSONObject(issuer))))throw new SecurityException("已撤销的成员不能继续授权新设备");}
        JSONObject members=group.getJSONObject("members");for(String id:GroupCrypto.keys(old.getJSONObject("members"))){JSONObject cert=old.getJSONObject("members").getJSONObject(id);if(members.has(id)&&!GroupCrypto.same(members.getJSONObject(id).getJSONObject("member"),cert.getJSONObject("member")))throw new SecurityException();if(!members.has(id)||!advances(group,cert,members.getJSONObject(id)))members.put(id,cert);}
        GroupCrypto.refreshRemoved(old);JSONArray tokens=group.optJSONArray("revoked");if(tokens==null)tokens=new JSONArray();for(int i=0;i<old.getJSONArray("revoked").length();i++)GroupCrypto.add(tokens,old.getJSONArray("revoked").getString(i));group.put("revoked",tokens);GroupCrypto.refreshRemoved(group);
        JSONObject feeds=group.getJSONObject("feeds"),oldFeeds=old.getJSONObject("feeds");for(String id:GroupCrypto.keys(oldFeeds))if(!feeds.has(id)||oldFeeds.getJSONObject(id).getLong("sequence")>feeds.getJSONObject(id).getLong("sequence"))feeds.put(id,oldFeeds.getJSONObject(id));
        group.put("lastSync",Math.max(group.optLong("lastSync"),old.optLong("lastSync")));group.put("enabled",old.optBoolean("enabled",true));group.put("suppressedPeers",old.optJSONArray("suppressedPeers")==null?new JSONArray():old.getJSONArray("suppressedPeers"));group.put("publishedSequence",Math.max(old.optLong("publishedSequence"),group.optLong("publishedSequence")));
        JSONArray groups=state.getJSONArray("groups");for(int i=0;i<groups.length();i++)if(groups.getJSONObject(i).getString("id").equals(group.getString("id"))){groups.put(i,group);break;}return group;
    }
    static JSONObject install(JSONObject state,JSONObject group)throws Exception{GroupCrypto.validate(group);JSONObject identity=state.getJSONObject("identity");String own=identity.getJSONObject("member").getString("id"),id=group.getString("id");JSONObject certificate=group.getJSONObject("members").getJSONObject(own);if(!GroupCrypto.same(certificate.getJSONObject("member"),identity.getJSONObject("member"))||GroupCrypto.contains(group.getJSONArray("removed"),own))throw new SecurityException("本机入组授权无效");JSONObject old=find(state,id);if(old!=null){GroupCrypto.refreshRemoved(old);if(!GroupCrypto.contains(old.getJSONArray("removed"),own)&&(!GroupCrypto.contains(group.getJSONArray("revoked"),GroupCrypto.revocation(old.getJSONObject("members").getJSONObject(own)))||GroupCrypto.certHash(certificate).equals(GroupCrypto.certHash(old.getJSONObject("members").getJSONObject(own)))))throw new IllegalStateException("本机已加入此同步组");if(!GroupCrypto.certHash(old.getJSONObject("root")).equals(GroupCrypto.certHash(group.getJSONObject("root")))||!old.getString("directoryKey").equals(group.getString("directoryKey"))||certificate.optString("admission").isEmpty()||GroupCrypto.certHash(certificate).equals(GroupCrypto.certHash(old.getJSONObject("members").getJSONObject(own))))throw new SecurityException("重新加入需要新的设备授权");JSONArray revoked=group.getJSONArray("revoked"),previous=old.getJSONArray("revoked");for(int i=0;i<previous.length();i++)GroupCrypto.add(revoked,previous.getString(i));}
        JSONObject prior=group.getJSONObject("feeds").optJSONObject(own);JSONArray certs=new JSONArray(),removed=new JSONArray();Set<String> hashes=new HashSet<>();for(JSONObject source:new JSONObject[]{old,prior}){if(source==null)continue;JSONArray cs=source.optJSONArray(source==old?"ownCertificates":"certificates"),rs=source.optJSONArray(source==old?"ownRemoved":"removed");if(cs!=null)for(int i=0;i<cs.length();i++){JSONObject c=cs.getJSONObject(i);String mid=c.getJSONObject("member").getString("id");if(group.getJSONObject("members").has(mid)&&GroupCrypto.same(group.getJSONObject("members").getJSONObject(mid).getJSONObject("member"),c.getJSONObject("member"))&&hashes.add(GroupCrypto.certHash(c)))certs.put(c);}if(rs!=null)for(int i=0;i<rs.length();i++)GroupCrypto.add(removed,rs.getString(i));}
        group.put("ownCertificates",certs).put("ownRemoved",removed).put("sequence",Math.max(old==null?0:old.optLong("sequence"),prior==null?0:prior.optLong("sequence"))+1).put("enabled",true).put("publishedSequence",0).put("publishRetryAfter",0).put("checkedAt",0).put("suppressedPeers",new JSONArray());group.getJSONObject("feeds").put(own,GroupCrypto.feed(group,identity));GroupCrypto.refreshRemoved(group);if(GroupCrypto.contains(group.getJSONArray("removed"),own)||GroupCrypto.contains(group.getJSONArray("removed"),certificate.getString("issuer")))throw new SecurityException("当前邀请授权已被撤销");JSONArray gs=state.getJSONArray("groups");for(int i=gs.length()-1;i>=0;i--)if(gs.getJSONObject(i).getString("id").equals(id))gs.remove(i);JSONArray deleted=state.optJSONArray("deletedGroups");if(deleted!=null)for(int i=deleted.length()-1;i>=0;i--)if(id.equals(deleted.getString(i)))deleted.remove(i);return merge(state,group);
    }
    static String legacyId(JSONObject p)throws Exception{String peer=p.optString("peerIdentity");return "legacy:"+(peer.length()==32?peer:p.getJSONObject("config").getString("pair"));}
    static JSONArray overview(JSONObject state,JSONArray profiles)throws Exception{
        JSONArray result=new JSONArray(),groups=state.getJSONArray("groups");String self=state.optJSONObject("identity")==null?"":state.getJSONObject("identity").getJSONObject("member").getString("id");
        for(int i=0;i<groups.length();i++){JSONObject g=groups.getJSONObject(i);long last=g.optLong("lastSync");for(int n=0;n<profiles.length();n++){JSONObject p=profiles.getJSONObject(n);if(p.optString("groupId").equals(g.getString("id")))last=Math.max(last,p.optLong("lastSync"));}int count=0;for(String id:GroupCrypto.keys(g.getJSONObject("members")))if(!GroupCrypto.contains(g.getJSONArray("removed"),id))count++;boolean left=GroupCrypto.contains(g.getJSONArray("removed"),self);result.put(new JSONObject().put("id",g.getString("id")).put("name",g.getString("name")).put("enabled",g.optBoolean("enabled",true)&&!left).put("left",left).put("legacy",false).put("members",count).put("server",g.getJSONObject("connection").getString("server")).put("transport",g.getJSONObject("connection").optString("transport")).put("status",left?"已退出":!g.optBoolean("enabled",true)?"已关闭":g.optString("status","等待连接")).put("lastSync",last));}
        Map<String,JSONObject> legacy=new LinkedHashMap<>();for(int i=0;i<profiles.length();i++){JSONObject p=profiles.getJSONObject(i);if(!p.optString("groupId").isEmpty())continue;String id=legacyId(p);JSONObject row=legacy.get(id);if(row==null){JSONObject c=p.getJSONObject("config");row=new JSONObject().put("id",id).put("name",p.optString("name").isEmpty()?"双设备同步组":p.getString("name")).put("legacy",true).put("members",2).put("enabled",false).put("lastSync",0).put("server",c.getString("server")).put("transport",c.optString("transport","relay")).put("status","双设备组");legacy.put(id,row);}row.put("enabled",row.getBoolean("enabled")||p.optBoolean("enabled",true));row.put("lastSync",Math.max(row.optLong("lastSync"),p.optLong("lastSync")));}for(JSONObject row:legacy.values())result.put(row);return result;
    }
    static void captureLastSync(JSONObject state,JSONArray profiles)throws Exception{JSONArray groups=state.getJSONArray("groups");for(int i=0;i<groups.length();i++){JSONObject group=groups.getJSONObject(i);long last=group.optLong("lastSync");for(int n=0;n<profiles.length();n++){JSONObject p=profiles.getJSONObject(n);if(p.optString("groupId").equals(group.getString("id")))last=Math.max(last,p.optLong("lastSync"));}group.put("lastSync",last);}}
    static boolean apply(JSONObject state,JSONArray profiles,JSONObject stones)throws Exception{
        if(!state.has("identity"))return false;JSONObject identity=state.getJSONObject("identity");String self=identity.getJSONObject("member").getString("id");Map<String,JSONObject> desired=new LinkedHashMap<>();JSONArray groups=state.getJSONArray("groups");
        for(int i=0;i<groups.length();i++){JSONObject g=groups.getJSONObject(i);GroupCrypto.validate(g);if(!g.optBoolean("enabled",true)||GroupCrypto.contains(g.getJSONArray("removed"),self))continue;JSONArray suppressed=g.optJSONArray("suppressedPeers");for(String id:GroupCrypto.keys(g.getJSONObject("members"))){if(id.equals(self)||GroupCrypto.contains(g.getJSONArray("removed"),id)||suppressed!=null&&GroupCrypto.contains(suppressed,id))continue;JSONObject m=g.getJSONObject("members").getJSONObject(id).getJSONObject("member"),config=GroupCrypto.channel(g,identity,m);JSONObject row=new JSONObject().put("config",config).put("enabled",true).put("groupId",g.getString("id")).put("groupPeer",id).put("groupKey",GroupCrypto.hash(GroupCrypto.bytes(m.getString("signingKey")))).put("name",m.getString("name")).put("peerIdentity",id);desired.put(config.getString("pair"),row);}}
        boolean changed=false;for(int i=profiles.length()-1;i>=0;i--){JSONObject p=profiles.getJSONObject(i);String pair=p.getJSONObject("config").getString("pair");if(!p.optString("groupId").isEmpty()&&!desired.containsKey(pair)){JSONObject old=p.getJSONObject("state");old.remove("pending");stones.put(pair,old);profiles.remove(i);changed=true;}}
        for(String pair:desired.keySet()){boolean exists=false;for(int i=0;i<profiles.length();i++)if(profiles.getJSONObject(i).getJSONObject("config").getString("pair").equals(pair)){JSONObject old=profiles.getJSONObject(i);if(!old.getJSONObject("config").getString("key").equals(desired.get(pair).getJSONObject("config").getString("key")))throw new SecurityException("连接密钥不一致");exists=true;break;}if(exists)continue;if(profiles.length()>=16){for(int i=0;i<groups.length();i++)if(groups.getJSONObject(i).getString("id").equals(desired.get(pair).getString("groupId")))groups.getJSONObject(i).put("status","配置已达 16 套上限，请移除不再使用的配置");continue;}JSONObject row=desired.get(pair),saved=stones.optJSONObject(pair);if(saved==null)saved=new JSONObject().put("clock",0).put("winner","");saved.remove("pending");row.put("state",saved);profiles.put(row);changed=true;}
        return changed;
    }
}
